INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ariq-boke','阿里不哥','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["大汗"]','阿里不哥是拖雷幼子，蒙哥死后在和林即大汗位，与忽必烈形成双重汗廷。双方争战至1264年阿里不哥降服，忽必烈由此巩固蒙古帝国最高权位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/阿里不哥"},{"label":"《元史·阿里不哥传》（维基文库）","url":"https://zh.wikisource.org/wiki/元史/卷004"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guyuk','贵由','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["大汗"]','贵由，窝阔台长子，1246年经忽里勒台即大汗位。其在位时间短，曾试图加强大汗对诸王和军队的控制，并与拔都关系紧张；1248年西行途中去世，之后皇后斡兀立海迷失摄政。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/贵由"}]','钦定皇帝','定宗','贵由汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('hu-bilie','忽必烈','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["大汗","皇帝"]','拖雷之子、成吉思汗之孙。1251年蒙哥即大汗位后，受命经营漠南汉地，1253年率军征服大理，积累自己的军政力量。蒙哥死后，1260年被拥立为大汗，与阿里不哥争位，1264年获胜。1271年定国号大元，以大都为都，1279年灭南宋，完成统一；1294年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/忽必烈"},{"label":"《元典章·建国号诏》","url":"https://zh.wikisource.org/zh-hant/建國號詔"}]',NULL,'世祖','元世祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('mongke','蒙哥','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["大汗"]','蒙哥，拖雷长子，1251年经忽里勒台推举为大汗。即位后整顿财政与人口登记，并派旭烈兀西征、命忽必烈经略南方；1259年攻宋期间在钓鱼城下去世，随后忽必烈与阿里不哥争位，帝国统合受到冲击。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蒙哥"}]','桓肃皇帝','宪宗','蒙哥汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ogedei','窝阔台','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["大汗"]','窝阔台，成吉思汗第三子，1229年经忽里勒台推举为大汗。其朝继续西征并于1234年灭金，扩展蒙古在中原和中亚的统治；任用耶律楚材治理华北，营建哈剌和林，去世后由皇后脱列哥那摄政。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/窝阔台"}]','英文皇帝','太宗','窝阔台汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('temujin','铁木真','yuan','[]',NULL,NULL,1162,NULL,NULL,'year',1227,NULL,NULL,'year','["大汗"]','蒙古孛儿只斤氏，也速该之子。父死后部众离散，铁木真依靠家族与联盟重建力量，先与克烈部首领脱斡邻勒合作，后与札木合等争夺部众。1203年击败克烈部，1204年击败乃蛮，逐渐统一蒙古诸部；1206年获推举为成吉思汗。此后征西夏、金及中亚，1227年在征夏期间去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/成吉思汗"}]','法天启运圣武皇帝','太祖','成吉思汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tolui','拖雷','yuan','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["宗王"]','成吉思汗幼子，1227–1229年监国，蒙哥、忽必烈、阿里不哥之父。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/拖雷"}]',NULL,NULL,NULL,'[]');
